-- Anvex seed for the Rebix public catalog.
-- Generated by scripts/export-seed-sql.ts from the captured /allEnds manifest.
-- Manifest timestamp: 2026-10-17T16:39:11.102Z
-- Safe to re-run: existing endpoints (source_key), categories and models are kept.
-- Run this in the Supabase SQL editor or with psql after applying supabase/migrations.

do $$
declare
  seed jsonb := convert_from(decode('', 'base64'), 'utf8')::jsonb;
  provider_id uuid;
  category_id uuid;
  model_api_id uuid;
  item jsonb;
begin
  insert into public.providers
    (slug, name, description, homepage_url, base_url, docs_url, allowed_hosts, discovery_adapter, discovery_config)
  values
    ('rebix', 'Rebix API',
     'Public multi-purpose API provider discovered at api-rebix.zone.id. Catalog imported from its public /allEnds manifest.',
     'https://api-rebix.zone.id/', 'https://api-rebix.zone.id', 'https://api-rebix.zone.id/',
     array['api-rebix.zone.id'], 'rebix_manifest', '{"manifest_path":"/allEnds"}'::jsonb)
  on conflict (slug) do update set
    name = excluded.name,
    description = excluded.description,
    homepage_url = excluded.homepage_url,
    base_url = excluded.base_url,
    docs_url = excluded.docs_url,
    allowed_hosts = excluded.allowed_hosts,
    discovery_adapter = excluded.discovery_adapter,
    discovery_config = excluded.discovery_config
  returning id into provider_id;

  for item in select * from jsonb_array_elements(seed) loop
    insert into public.categories (slug, name, description)
    values (
      item->>'category_slug',
      coalesce(item->>'category_name', item->>'category_slug'),
      'Rebix ' || coalesce(item->>'category_name', item->>'category_slug') || ' endpoints.'
    )
    on conflict (slug) do nothing;

    select id into category_id from public.categories where slug = item->>'category_slug';

    insert into public.apis (
      owner_id, provider_id, category_id, slug, name, description, base_url, path, method,
      query_params, path_params, headers_schema, body_schema, auth_type, auth_config_meta,
      content_type, request_example, response_example, docs_url, source_url, discovery_source,
      discovery_metadata, verification_status, last_status_code, last_tested_at, last_error,
      is_public, is_enabled, is_nsfw, is_managed, allow_extra_query, supports_streaming,
      timeout_ms, source_key
    ) values (
      null, provider_id, category_id,
      item->>'slug', item->>'name', item->>'description',
      'https://api-rebix.zone.id', item->>'path', item->>'method',
      coalesce(item->'query_params', '[]'::jsonb), '[]'::jsonb, '[]'::jsonb, null,
      'none', '{}'::jsonb, 'application/json',
      item->'request_example', item->'response_example',
      'https://api-rebix.zone.id/', item->>'source_url', 'rebix_manifest',
      item->'discovery_metadata',
      (item->>'verification_status')::public.api_verification_status,
      case when item->>'verification_status' = 'unverified' then null else 200 end,
      case when item->>'verification_status' = 'unverified' then null else now() end,
      nullif(item->>'last_error', ''),
      true, true, coalesce((item->>'is_nsfw')::boolean, false), true, false, false,
      15000, item->>'source_key'
    )
    on conflict (source_key) do nothing;
  end loop;

  insert into public.ai_models (
    owner_id, provider_id, api_id, slug, name, description, adapter, chat_path,
    auth_type, auth_config_meta, config, capabilities, is_public, is_enabled
  )
  select null, provider_id, a.id, m.slug, m.name, m.description, 'rebix_text', '/chat/completions',
         'none', '{}'::jsonb,
         jsonb_build_object('query_param', 'q', 'response_paths',
           jsonb_build_array('message', 'response', 'result', 'reply', 'answer')),
         '{"chat":true,"streaming":false,"tools":false,"usage":false}'::jsonb,
         true, m.enabled
  from (values
    ('rebix-claude-haiku', 'Claude Haiku via Rebix', '/api/claude-haiku', true),
    ('rebix-gemini', 'Gemini via Rebix', '/api/gemini', true),
    ('rebix-deepseek-v3', 'DeepSeek V3 via Rebix (disabled)', '/api/deepseek-v3', false)
  ) as m(slug, name, path, enabled)
  join public.apis a on a.path = m.path and a.method = 'GET'
  on conflict (slug) do nothing;

  if not exists (
    select 1 from public.discovery_runs where source_url = 'https://api-rebix.zone.id/'
  ) then
    insert into public.discovery_runs (
      user_id, provider_id, adapter, source_url, status, attempted_methods, notes,
      created_count, updated_count, unchanged_count, failed_count, endpoint_ids,
      started_at, finished_at
    ) values (
      null, provider_id, 'rebix_manifest', 'https://api-rebix.zone.id/', 'success',
      jsonb_build_array(
        jsonb_build_object('method', 'homepage', 'target', 'https://api-rebix.zone.id/', 'outcome', 'success', 'status', 200),
        jsonb_build_object('method', 'javascript_bundle_scan', 'target', 'https://api-rebix.zone.id/script.js', 'outcome', 'success', 'status', 200),
        jsonb_build_object('method', 'manifest_probe', 'target', 'https://api-rebix.zone.id/allEnds', 'outcome', 'success', 'status', 200, 'endpoints', 55),
        jsonb_build_object('method', 'openapi_probe', 'target', 'https://api-rebix.zone.id/openapi.json', 'outcome', 'not_found', 'status', 404),
        jsonb_build_object('method', 'openapi_probe', 'target', 'https://api-rebix.zone.id/swagger.json', 'outcome', 'not_found', 'status', 404)
      ),
      'Seeded from a captured live discovery run. Verification reflects real requests: 7 verified, 2 failed with upstream 422, 46 unverified.',
      55, 0, 0, 0,
      array(select id from public.apis),
      '2026-10-17T16:39:11.102Z'::timestamptz, now()
    );
  end if;

  -- Keep the provider's category list aligned even when no endpoints exist.
  insert into public.categories (slug, name, description)
  values ('stalk', 'Stalk', 'No publicly documented routes existed at discovery time.')
  on conflict (slug) do nothing;

  -- ai: 8 endpoints
  -- downloader: 11 endpoints
  -- search: 9 endpoints
  -- anime: 1 endpoints
  -- tools: 5 endpoints
  -- tools-extra: 5 endpoints
  -- random: 3 endpoints
  -- images: 7 endpoints
  -- nsfw: 5 endpoints
  -- system: 1 endpoints
end $$;
